using var adapter = new LabScriptedAdapter();
foreach (int value in new[] { -1, 0, 100, 101 })
{
    var reply = adapter.Send(new LabCommand($"R{value}", 1, "SetLevel", "D1", value));
    Console.WriteLine($"{value}: {reply.Accepted} {reply.Code}");
}
var typo = adapter.Send(new LabCommand("RX", 1, "setlevel", "D1", 20));
Console.WriteLine(typo.Code); // UnsupportedAction
Console.WriteLine(adapter.Sent.Count); // 2

using System.Text.Json;
foreach (string text in new[] { """{"Action":"SetLevel"}""", """{"Action":"SetLevel","Value":0}""" })
{
    using var doc = JsonDocument.Parse(text);
    var root = doc.RootElement;
    if (!root.TryGetProperty("Value", out var field)) { Console.WriteLine("MissingValue"); continue; }
    if (field.ValueKind != JsonValueKind.Number || !field.TryGetInt32(out int value)) { Console.WriteLine("InvalidType"); continue; }
    Console.WriteLine(value is >= 0 and <= 100 ? $"Valid:{value}" : "OutOfRange");
}
